-- Run after 007_public_gallery.sql. Imports eight existing AI portraits into the
-- database. Starter quality rating: 8/10. No customer photos or scores are changed.
begin;
create table if not exists public.fd_lookbook_inspiration (
  id uuid primary key default gen_random_uuid(),
  seed_key text not null unique,
  title text not null check(length(title) between 1 and 100),
  breed text not null check(length(breed)<=180),
  caption text not null check(length(caption)<=120),
  image_data text not null check(length(image_data)<=2000000 and image_data ~ '^data:image/(jpeg|png|webp);base64,[A-Za-z0-9+/]+=*$'),
  quality_score smallint check(quality_score between 1 and 10),
  published boolean not null default true,
  created_at timestamptz not null default now()
);
alter table public.fd_lookbook_inspiration enable row level security;
revoke all on public.fd_lookbook_inspiration from public,anon,authenticated;

-- Re-running the import never overwrites a later rating, publication choice or date.
insert into public.fd_lookbook_inspiration(id,seed_key,title,breed,caption,image_data,quality_score) values
('fdfd0000-0000-4000-8000-000000000008','bichon-frise','Bichon Frise','Bichon Frise','Round & fluffy','data:image/jpeg;base64,',8),
('fdfd0000-0000-4000-8000-000000000007','yorkie','Yorkie','Yorkie','Short & tidy','data:image/jpeg;base64,',8),
('fdfd0000-0000-4000-8000-000000000006','cocker-spaniel','Cocker Spaniel','Cocker Spaniel','Long & silky','data:image/jpeg;base64,',8),
('fdfd0000-0000-4000-8000-000000000005','poodle','Poodle','Poodle','Soft & rounded','data:image/jpeg;base64,',8),
('fdfd0000-0000-4000-8000-000000000004','schnauzer','Schnauzer','Schnauzer','Neat beard','data:image/jpeg;base64,',8),
('fdfd0000-0000-4000-8000-000000000003','shih-tzu','Shih Tzu','Shih Tzu','Puppy cut','data:image/jpeg;base64,',8),
('fdfd0000-0000-4000-8000-000000000002','doodle','Doodle','Doodle','Teddy trim','data:image/jpeg;base64,',8),
('fdfd0000-0000-4000-8000-000000000001','wheaten-terrier','Wheaten Terrier','Wheaten Terrier','Natural fall','data:image/jpeg;base64,',8)
on conflict(seed_key) do nothing;

-- One public selection source, sorted by upload/import date by the callers.
-- Unrated photos and scores of 1 do not qualify. Inspiration has no fake owner,
-- dog profile, groomer or location, and never matches owner/groomer-only filters.
create or replace view public.fd_gallery_source as
select p.id,p.caption,d.name as dog_name,d.breed,p.provider_id,p.provider_label,
  coalesce(loc.label,'') as location_label,p.uploader_type,p.created_at,p.quality_score
from public.fd_dog_photos p
join public.fd_dogs d on d.id=p.dog_id and d.owner_id=p.owner_id
left join lateral (
  select string_agg(distinct c.name||', '||c.state,' / ' order by c.name||', '||c.state) label
  from public.fd_directory_coverage v join public.fd_directory_cities c on c.id=v.city_id
  where v.business_id=p.provider_id
) loc on true
where p.visibility='public' and p.quality_score>1
  and not exists(select 1 from public.fd_lookbook_inspiration i where i.id=p.id)
union all
select i.id,i.caption,i.title as dog_name,i.breed,null::uuid as provider_id,''::text as provider_label,
  ''::text as location_label,'inspiration'::text as uploader_type,i.created_at,i.quality_score
from public.fd_lookbook_inspiration i where i.published and i.quality_score>1;
revoke all on public.fd_gallery_source from public,anon,authenticated;

create or replace function public.fd_gallery_featured()
returns table(id uuid,caption text,dog_name text,breed text,provider_id uuid,provider_label text,location_label text,uploader_type text,created_at timestamptz)
language sql stable security definer set search_path='' as $$
  select g.id,g.caption,g.dog_name,g.breed,g.provider_id,g.provider_label,g.location_label,g.uploader_type,g.created_at
  from public.fd_gallery_source g order by g.created_at desc,g.id desc limit 8;
$$;

create or replace function public.fd_gallery_image(p_photo_id uuid) returns table(image_data text)
language sql stable security definer set search_path='' as $$
  select p.image_data from public.fd_dog_photos p
  where p.id=p_photo_id and p.visibility='public' and p.quality_score>1
    and not exists(select 1 from public.fd_lookbook_inspiration i where i.id=p.id)
  union all
  select i.image_data from public.fd_lookbook_inspiration i
  where i.id=p_photo_id and i.published and i.quality_score>1 limit 1;
$$;

create or replace function public.fd_public_lookbook(p_offset integer default 0)
returns table(id uuid,image_data text,caption text,dog_name text,breed text,provider_id uuid,provider_label text,created_at timestamptz)
language sql stable security definer set search_path='' as $$
  select g.id,photo.image_data,g.caption,g.dog_name,g.breed,g.provider_id,g.provider_label,g.created_at
  from public.fd_gallery_source g cross join lateral public.fd_gallery_image(g.id) photo
  where p_offset between 0 and 10000
  order by g.created_at desc,g.id desc limit 12 offset greatest(0,least(coalesce(p_offset,0),10000));
$$;
revoke all on function public.fd_gallery_featured(),public.fd_gallery_image(uuid),public.fd_public_lookbook(integer) from public,anon,authenticated;
grant execute on function public.fd_gallery_featured(),public.fd_gallery_image(uuid),public.fd_public_lookbook(integer) to anon,authenticated;
notify pgrst,'reload schema';
commit;
